{"code": "import math

def compute_S(N):
    s = 0
    for j in range(1, N):
        for k in range(1, N):
            s += 1 / (j + k)**3
    return s

def compute_pq(N):
    p = sum(1/k**2 for k in range(1, N))
    q = sum(1/k**3 for k in range(1, N))
    return p, q

N = 10000
S_approx = compute_S(N)
p_approx, q_approx = compute_pq(N)
print(f"S approx: {S_approx}")
print(f"p - q approx: {p_approx - q_approx}")"}
